@router.post("/hx/v1/contracts/{contract_id}/sign-inline", response_class=HTMLResponse)
def sign_contract_inline(
    contract_id: int,
    signer_name: str = Form(...),
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    contract = db.query(Contract).filter(
        Contract.id == contract_id,
        Contract.counterparty_user_id == current_user.id
    ).first()
    if not contract:
        raise HTTPException(status_code=404, detail="Contract not found or unauthorized")
    contract.status = "EXECUTED"
    contract.executed_by_name = signer_name
    contract.signed_at = datetime.utcnow()
    db.commit()
    return HTMLResponse(f'<div id="contract-status" class="badge-success">Signed by {signer_name}</div>')
